from typing import List

class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)

        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        neg_inf = float("-inf")
        prev = [0] * (n + 1)

        for _ in range(k):
            curr = [neg_inf] * (n + 1)
            best = neg_inf

            for i in range(1, n + 1):
                if i >= m and prev[i - m] != neg_inf:
                    best = max(best, prev[i - m] - prefix[i - m])

                curr[i] = curr[i - 1]

                if best != neg_inf:
                    curr[i] = max(curr[i], prefix[i] + best)

            prev = curr

        return prev[n]
